/** Configuration for the `prometheus` (Prometheus) plugin. */
export interface PrometheusConfig {
  /**
   * A boolean value that determines if ai metrics should be collected. If enabled, the `ai_llm_requests_total`, `ai_llm_cost_total` and `ai_llm_tokens_total` metrics will be exported.
   * @default false
   */
  ai_metrics?: boolean | null;
  /**
   * A boolean value that determines if bandwidth metrics should be collected. If enabled, `bandwidth_bytes` and `stream_sessions_total` metrics will be exported.
   * @default false
   */
  bandwidth_metrics?: boolean | null;
  /**
   * A boolean value that determines if latency metrics should be collected. If enabled, `kong_latency_ms`, `upstream_latency_ms` and `request_latency_ms` metrics will be exported.
   * @default false
   */
  latency_metrics?: boolean | null;
  /**
   * A boolean value that determines if per-consumer metrics should be collected. If enabled, the `kong_http_requests_total` and `kong_bandwidth_bytes` metrics fill in the consumer label when available.
   * @default false
   */
  per_consumer?: boolean | null;
  /**
   * A boolean value that determines if status code metrics should be collected. If enabled, `http_requests_total`, `stream_sessions_total` metrics will be exported.
   * @default false
   */
  status_code_metrics?: boolean | null;
  /**
   * A boolean value that determines if upstream metrics should be collected. If enabled, `upstream_target_health` metric will be exported.
   * @default false
   */
  upstream_health_metrics?: boolean | null;
  /** Kong Gateway 3.14 only. */
  wasm_metrics?: boolean | null;
}

/** Configuration for the `proxy-cache` (Proxy Cache) plugin. */
export interface ProxyCacheConfig {
  /**
   * When enabled, respect the Cache-Control behaviors defined in RFC7234.
   * @default false
   */
  cache_control?: boolean | null;
  /**
   * TTL, in seconds, of cache entities.
   * @default 300
   */
  cache_ttl?: number | null;
  /**
   * Upstream response content types considered cacheable. The plugin performs an **exact match** against each specified value.
   * @default ["text/plain","application/json"]
   */
  content_type?: Array<string> | null;
  /** @default false */
  ignore_uri_case?: boolean | null;
  memory?: {
    /**
     * The name of the shared dictionary in which to hold cache entities when the memory strategy is selected. Note that this dictionary currently must be defined manually in the Kong Nginx template.
     * @default 'kong_db_cache'
     */
    dictionary_name?: string | null;
  } | null;
  /**
   * Downstream request methods considered cacheable.
   * @default ["GET","HEAD"]
   */
  request_method?: Array<'GET' | 'HEAD' | 'PATCH' | 'POST' | 'PUT'> | null;
  /**
   * Upstream response status code considered cacheable.
   * @default [200,301,404]
   */
  response_code?: Array<number> | null;
  /** Caching related diagnostic headers that should be included in cached responses */
  response_headers?: {
    /** @default true */
    age?: boolean | null;
    /** @default true */
    'X-Cache-Key'?: boolean | null;
    /** @default true */
    'X-Cache-Status'?: boolean | null;
  } | null;
  /** Number of seconds to keep resources in the storage backend. This value is independent of `cache_ttl` or resource TTLs defined by Cache-Control behaviors. */
  storage_ttl?: number | null;
  /** The backing data store in which to hold cache entities. */
  strategy: 'memory';
  /** Relevant headers considered for the cache key. If undefined, none of the headers are taken into consideration. */
  vary_headers?: Array<string> | null;
  /** Relevant query parameters considered for the cache key. If undefined, all params are taken into consideration. */
  vary_query_params?: Array<string> | null;
}

/** Configuration for the `rate-limiting` (Rate Limiting) plugin. */
export interface RateLimitingConfig {
  /** The number of HTTP requests that can be made per day. */
  day?: number | null;
  /**
   * Set a custom error code to return when the rate limit is exceeded.
   * @default 429
   */
  error_code?: number | null;
  /**
   * Set a custom error message to return when the rate limit is exceeded.
   * @default 'API rate limit exceeded'
   */
  error_message?: string | null;
  /**
   * A boolean value that determines if the requests should be proxied even if Kong has troubles connecting a third-party data store. If `true`, requests will be proxied anyway, effectively disabling the rate-limiting function until the data store is working again. If `false`, then the clients will see `500` errors.
   * @default true
   */
  fault_tolerant?: boolean | null;
  /** A string representing an HTTP header name. */
  header_name?: string | null;
  /**
   * Optionally hide informative response headers.
   * @default false
   */
  hide_client_headers?: boolean | null;
  /** The number of HTTP requests that can be made per hour. */
  hour?: number | null;
  /**
   * The entity that is used when aggregating the limits.
   * Kong Gateway 3.14 only values: `'consumer-group'`.
   * @default 'consumer'
   */
  limit_by?:
    | 'consumer'
    | 'credential'
    | 'header'
    | 'ip'
    | 'path'
    | 'service'
    | 'consumer-group'
    | null;
  /** The number of HTTP requests that can be made per minute. */
  minute?: number | null;
  /** The number of HTTP requests that can be made per month. */
  month?: number | null;
  /** A string representing a URL path, such as /path/to/resource. Must start with a forward slash (/) and must not contain empty segments (i.e., two consecutive forward slashes). */
  path?: string | null;
  /**
   * The rate-limiting policies to use for retrieving and incrementing the limits.
   * @default 'local'
   */
  policy?: 'cluster' | 'local' | 'redis' | null;
  /** Redis configuration */
  redis?: {
    /**
     * Database to use for the Redis connection when using the `redis` strategy
     * @default 0
     */
    database?: number | null;
    /** A string representing a host name, such as example.com. */
    host?: string | null;
    /** Password to use for Redis connections. If undefined, no AUTH commands are sent to Redis. */
    password?: string | null;
    /**
     * An integer representing a port number between 0 and 65535, inclusive.
     * @default 6379
     */
    port?: number | null;
    /** A string representing an SNI (server name indication) value for TLS. */
    server_name?: string | null;
    /**
     * If set to true, uses SSL to connect to Redis.
     * @default false
     */
    ssl?: boolean | null;
    /**
     * If set to true, verifies the validity of the server SSL certificate. If setting this parameter, also configure `lua_ssl_trusted_certificate` in `kong.conf` to specify the CA (or server) certificate used by your Redis server. You may also need to configure `lua_ssl_verify_depth` accordingly.
     * @default Kong 3.9: false; Kong Gateway 3.14: true
     */
    ssl_verify?: boolean | null;
    /**
     * An integer representing a timeout in milliseconds. Must be between 0 and 2^31-2.
     * @default 2000
     */
    timeout?: number | null;
    /** Username to use for Redis connections. If undefined, ACL authentication won't be performed. This requires Redis v6.0.0+. To be compatible with Redis v5.x.y, you can set it to `default`. */
    username?: string | null;
    /** Kong Gateway 3.14 only. */
    cloud_authentication?: {
      auth_provider?: 'aws' | 'azure' | 'gcp' | null;
      aws_access_key_id?: string | null;
      aws_assume_role_arn?: string | null;
      aws_cache_name?: string | null;
      /** @default true */
      aws_is_serverless?: boolean | null;
      aws_region?: string | null;
      aws_role_session_name?: string | null;
      aws_secret_access_key?: string | null;
      azure_client_id?: string | null;
      azure_client_secret?: string | null;
      azure_tenant_id?: string | null;
      gcp_service_account_json?: string | null;
    } | null;
  } | null;
  /** The number of HTTP requests that can be made per second. */
  second?: number | null;
  /**
   * How often to sync counter data to the central data store. A value of -1 results in synchronous behavior.
   * @default -1
   */
  sync_rate?: number | null;
  /** The number of HTTP requests that can be made per year. */
  year?: number | null;
  /** @deprecated rate-limiting: config.redis_database is deprecated, please use config.redis.database instead */
  redis_database?: number | null;
  /** @deprecated rate-limiting: config.redis_host is deprecated, please use config.redis.host instead */
  redis_host?: string | null;
  /** @deprecated rate-limiting: config.redis_password is deprecated, please use config.redis.password instead */
  redis_password?: string | null;
  /** @deprecated rate-limiting: config.redis_port is deprecated, please use config.redis.port instead */
  redis_port?: number | null;
  /** @deprecated rate-limiting: config.redis_server_name is deprecated, please use config.redis.server_name instead */
  redis_server_name?: string | null;
  /** @deprecated rate-limiting: config.redis_ssl is deprecated, please use config.redis.ssl instead */
  redis_ssl?: boolean | null;
  /** @deprecated rate-limiting: config.redis_ssl_verify is deprecated, please use config.redis.ssl_verify instead */
  redis_ssl_verify?: boolean | null;
  /** @deprecated rate-limiting: config.redis_timeout is deprecated, please use config.redis.timeout instead */
  redis_timeout?: number | null;
  /** @deprecated rate-limiting: config.redis_username is deprecated, please use config.redis.username instead */
  redis_username?: string | null;
}

/** Configuration for the `redirect` (Redirect) plugin. */
export interface RedirectConfig {
  /**
   * Use the incoming request's path and query string in the redirect URL
   * @default false
   */
  keep_incoming_path?: boolean | null;
  /** The URL to redirect to */
  location: string;
  /**
   * The response code to send. Must be an integer between 100 and 599.
   * @default 301
   */
  status_code?: number | null;
}

/** Configuration for the `request-size-limiting` (Request Size Limiting) plugin. */
export interface RequestSizeLimitingConfig {
  /**
   * Allowed request payload size in megabytes. Default is `128` megabytes (128000000 bytes).
   * @default 128
   */
  allowed_payload_size?: number | null;
  /**
   * Set to `true` to ensure a valid `Content-Length` header exists before reading the request body.
   * @default false
   */
  require_content_length?: boolean | null;
  /**
   * Size unit can be set either in `bytes`, `kilobytes`, or `megabytes` (default). This configuration is not available in versions prior to Kong Gateway 1.3 and Kong Gateway (OSS) 2.0.
   * @default 'megabytes'
   */
  size_unit?: 'bytes' | 'kilobytes' | 'megabytes' | null;
}

/** Configuration for the `request-termination` (Request Termination) plugin. */
export interface RequestTerminationConfig {
  /** The raw response body to send. This is mutually exclusive with the `config.message` field. */
  body?: string | null;
  /** Content type of the raw response configured with `config.body`. */
  content_type?: string | null;
  /**
   * When set, the plugin will echo a copy of the request back to the client. The main usecase for this is debugging. It can be combined with `trigger` in order to debug requests on live systems without disturbing real traffic.
   * @default false
   */
  echo?: boolean | null;
  /** The message to send, if using the default response generator. */
  message?: string | null;
  /**
   * The response code to send. Must be an integer between 100 and 599.
   * @default 503
   */
  status_code?: number | null;
  /** A string representing an HTTP header name. */
  trigger?: string | null;
}

/** Configuration for the `request-transformer` (Request Transformer) plugin. */
export interface RequestTransformerConfig {
  add?: {
    /** @default [] */
    body?: Array<string> | null;
    /** @default [] */
    headers?: Array<string> | null;
    /** @default [] */
    querystring?: Array<string> | null;
  } | null;
  append?: {
    /** @default [] */
    body?: Array<string> | null;
    /** @default [] */
    headers?: Array<string> | null;
    /** @default [] */
    querystring?: Array<string> | null;
  } | null;
  /** A string representing an HTTP method, such as GET, POST, PUT, or DELETE. The string must contain only uppercase letters. */
  http_method?: string | null;
  remove?: {
    /** @default [] */
    body?: Array<string> | null;
    /** @default [] */
    headers?: Array<string> | null;
    /** @default [] */
    querystring?: Array<string> | null;
  } | null;
  rename?: {
    /** @default [] */
    body?: Array<string> | null;
    /** @default [] */
    headers?: Array<string> | null;
    /** @default [] */
    querystring?: Array<string> | null;
  } | null;
  replace?: {
    /** @default [] */
    body?: Array<string> | null;
    /** @default [] */
    headers?: Array<string> | null;
    /** @default [] */
    querystring?: Array<string> | null;
    uri?: string | null;
  } | null;
}

/** Configuration for the `response-ratelimiting` (Response Rate Limiting) plugin. */
export interface ResponseRatelimitingConfig {
  /**
   * A boolean value that determines if the requests should be blocked as soon as one limit is being exceeded. This will block requests that are supposed to consume other limits too.
   * @default false
   */
  block_on_first_violation?: boolean | null;
  /**
   * A boolean value that determines if the requests should be proxied even if Kong has troubles connecting a third-party datastore. If `true`, requests will be proxied anyway, effectively disabling the rate-limiting function until the datastore is working again. If `false`, then the clients will see `500` errors.
   * @default true
   */
  fault_tolerant?: boolean | null;
  /**
   * The name of the response header used to increment the counters.
   * @default 'x-kong-limit'
   */
  header_name?: string | null;
  /**
   * Optionally hide informative response headers.
   * @default false
   */
  hide_client_headers?: boolean | null;
  /**
   * The entity that will be used when aggregating the limits: `consumer`, `credential`, `ip`. If the `consumer` or the `credential` cannot be determined, the system will always fallback to `ip`.
   * @default 'consumer'
   */
  limit_by?: 'consumer' | 'credential' | 'ip' | null;
  /** A map that defines rate limits for the plugin. */
  limits: Record<
    string,
    {
      day?: number | null;
      hour?: number | null;
      minute?: number | null;
      month?: number | null;
      second?: number | null;
      year?: number | null;
    }
  >;
  /**
   * The rate-limiting policies to use for retrieving and incrementing the limits.
   * @default 'local'
   */
  policy?: 'cluster' | 'local' | 'redis' | null;
  /** Redis configuration */
  redis?: {
    /**
     * Database to use for the Redis connection when using the `redis` strategy
     * @default 0
     */
    database?: number | null;
    /** A string representing a host name, such as example.com. */
    host?: string | null;
    /** Password to use for Redis connections. If undefined, no AUTH commands are sent to Redis. */
    password?: string | null;
    /**
     * An integer representing a port number between 0 and 65535, inclusive.
     * @default 6379
     */
    port?: number | null;
    /** A string representing an SNI (server name indication) value for TLS. */
    server_name?: string | null;
    /**
     * If set to true, uses SSL to connect to Redis.
     * @default false
     */
    ssl?: boolean | null;
    /**
     * If set to true, verifies the validity of the server SSL certificate. If setting this parameter, also configure `lua_ssl_trusted_certificate` in `kong.conf` to specify the CA (or server) certificate used by your Redis server. You may also need to configure `lua_ssl_verify_depth` accordingly.
     * @default Kong 3.9: false; Kong Gateway 3.14: true
     */
    ssl_verify?: boolean | null;
    /**
     * An integer representing a timeout in milliseconds. Must be between 0 and 2^31-2.
     * @default 2000
     */
    timeout?: number | null;
    /** Username to use for Redis connections. If undefined, ACL authentication won't be performed. This requires Redis v6.0.0+. To be compatible with Redis v5.x.y, you can set it to `default`. */
    username?: string | null;
    /** Kong Gateway 3.14 only. */
    cloud_authentication?: {
      auth_provider?: 'aws' | 'azure' | 'gcp' | null;
      aws_access_key_id?: string | null;
      aws_assume_role_arn?: string | null;
      aws_cache_name?: string | null;
      /** @default true */
      aws_is_serverless?: boolean | null;
      aws_region?: string | null;
      aws_role_session_name?: string | null;
      aws_secret_access_key?: string | null;
      azure_client_id?: string | null;
      azure_client_secret?: string | null;
      azure_tenant_id?: string | null;
      gcp_service_account_json?: string | null;
    } | null;
  } | null;
  /** @deprecated response-ratelimiting: config.redis_database is deprecated, please use config.redis.database instead */
  redis_database?: number | null;
  /** @deprecated response-ratelimiting: config.redis_host is deprecated, please use config.redis.host instead */
  redis_host?: string | null;
  /** @deprecated response-ratelimiting: config.redis_password is deprecated, please use config.redis.password instead */
  redis_password?: string | null;
  /** @deprecated response-ratelimiting: config.redis_port is deprecated, please use config.redis.port instead */
  redis_port?: number | null;
  /** @deprecated response-ratelimiting: config.redis_server_name is deprecated, please use config.redis.server_name instead */
  redis_server_name?: string | null;
  /** @deprecated response-ratelimiting: config.redis_ssl is deprecated, please use config.redis.ssl instead */
  redis_ssl?: boolean | null;
  /** @deprecated response-ratelimiting: config.redis_ssl_verify is deprecated, please use config.redis.ssl_verify instead */
  redis_ssl_verify?: boolean | null;
  /** @deprecated response-ratelimiting: config.redis_timeout is deprecated, please use config.redis.timeout instead */
  redis_timeout?: number | null;
  /** @deprecated response-ratelimiting: config.redis_username is deprecated, please use config.redis.username instead */
  redis_username?: string | null;
}

/** Configuration for the `response-transformer` (Response Transformer) plugin. */
