/** Configuration for the `session` (Session) plugin. */
export interface SessionConfig {
  /**
   * The session cookie absolute timeout, in seconds. Specifies how long the session can be used until it is no longer valid.
   * @default 86400
   */
  absolute_timeout?: number | null;
  /**
   * The session audience, which is the intended target application. For example `"my-application"`.
   * @default 'default'
   */
  audience?: string | null;
  /** The domain with which the cookie is intended to be exchanged. */
  cookie_domain?: string | null;
  /**
   * Applies the `HttpOnly` tag so that the cookie is sent only to a server.
   * @default true
   */
  cookie_http_only?: boolean | null;
  /**
   * The name of the cookie.
   * @default 'session'
   */
  cookie_name?: string | null;
  /**
   * The resource in the host where the cookie is available.
   * @default '/'
   */
  cookie_path?: string | null;
  /**
   * Determines whether and how a cookie may be sent with cross-site requests.
   * @default 'Strict'
   */
  cookie_same_site?: 'Default' | 'Lax' | 'None' | 'Strict' | null;
  /**
   * Applies the Secure directive so that the cookie may be sent to the server only with an encrypted request over the HTTPS protocol.
   * @default true
   */
  cookie_secure?: boolean | null;
  /**
   * The session cookie idle time, in seconds.
   * @default 900
   */
  idling_timeout?: number | null;
  /**
   * A set of HTTP methods that the plugin will respond to.
   * @default ["POST","DELETE"]
   */
  logout_methods?: Array<'DELETE' | 'GET' | 'POST'> | null;
  /**
   * The POST argument passed to logout requests. Do not change this property.
   * @default 'session_logout'
   */
  logout_post_arg?: string | null;
  /**
   * The query argument passed to logout requests.
   * @default 'session_logout'
   */
  logout_query_arg?: string | null;
  /** @default false */
  read_body_for_logout?: boolean | null;
  /**
   * Enables or disables persistent sessions.
   * @default false
   */
  remember?: boolean | null;
  /**
   * The persistent session absolute timeout limit, in seconds.
   * @default 2592000
   */
  remember_absolute_timeout?: number | null;
  /**
   * Persistent session cookie name. Use with the `remember` configuration parameter.
   * @default 'remember'
   */
  remember_cookie_name?: string | null;
  /**
   * The persistent session rolling timeout window, in seconds.
   * @default 604800
   */
  remember_rolling_timeout?: number | null;
  /** List of information to include, as headers, in the response to the downstream. */
  request_headers?: Array<
    | 'absolute-timeout'
    | 'audience'
    | 'id'
    | 'idling-timeout'
    | 'rolling-timeout'
    | 'subject'
    | 'timeout'
  > | null;
  /** List of information to include, as headers, in the response to the downstream. */
  response_headers?: Array<
    | 'absolute-timeout'
    | 'audience'
    | 'id'
    | 'idling-timeout'
    | 'rolling-timeout'
    | 'subject'
    | 'timeout'
  > | null;
  /**
   * The session cookie rolling timeout, in seconds. Specifies how long the session can be used until it needs to be renewed.
   * @default 3600
   */
  rolling_timeout?: number | null;
  /** The secret that is used in keyed HMAC generation. */
  secret?: string | null;
  /**
   * The duration, in seconds, after which an old cookie is discarded, starting from the moment when the session becomes outdated and is replaced by a new one.
   * @default 10
   */
  stale_ttl?: number | null;
  /**
   * Determines where the session data is stored. `kong`: Stores encrypted session data into Kong's current database strategy; the cookie will not contain any session data. `cookie`: Stores encrypted session data within the cookie itself.
   * @default 'cookie'
   */
  storage?: 'cookie' | 'kong' | null;
  /** Kong Gateway 3.14 only. */
  bind?: Array<'ip' | 'scheme' | 'user-agent'> | null;
  /**
   * Kong Gateway 3.14 only.
   * @default false
   */
  hash_subject?: boolean | null;
  /**
   * Kong Gateway 3.14 only.
   * @default false
   */
  store_metadata?: boolean | null;
  cookie_discard?: number | null;
  cookie_httponly?: boolean | null;
  cookie_idletime?: number | null;
  cookie_lifetime?: number | null;
  cookie_persistent?: boolean | null;
  cookie_renew?: number | null;
  cookie_samesite?: string | null;
}

/** Configuration for the `standard-webhooks` (Standard Webhooks) plugin. */
export interface StandardWebhooksConfig {
  /** Webhook secret */
  secret_v1: string;
  /**
   * Tolerance of the webhook timestamp in seconds. If the webhook timestamp is older than this number of seconds, it will be rejected with a '400' response.
   * @default 300
   */
  tolerance_second?: number | null;
}

/** Configuration for the `statsd` (StatsD) plugin. */
export interface StatsdConfig {
  /** List of status code ranges that are allowed to be logged in metrics. */
  allow_status_codes?: Array<string> | null;
  /** @default 'custom_id' */
  consumer_identifier_default?: 'consumer_id' | 'custom_id' | 'username' | null;
  /** @deprecated statsd: config.flush_timeout is deprecated, please use config.queue.max_coalescing_delay instead */
  flush_timeout?: number | null;
  /**
   * The IP address or hostname of StatsD server to send data to.
   * @default 'localhost'
   */
  host?: string | null;
  /** @default false */
  hostname_in_prefix?: boolean | null;
  /**
   * List of metrics to be logged.
   * @default Kong 3.9: [{"name":"request_count","sample_rate":1,"stat_type":"counter"},{"name":"latency","stat_type":"timer"},{"name":"request_size","sample_rate":1,"stat_type":"counter"},{"name":"status_count","sample_rate":1,"stat_type":"counter"},{"name":"response_size","sample_rate":1,"stat_type":"counter"},{"name":"unique_users","stat_type":"set"},{"name":"request_per_user","sample_rate":1,"stat_type":"counter"},{"name":"upstream_latency","stat_type":"timer"},{"name":"kong_latency","stat_type":"timer"},{"name":"status_count_per_user","sample_rate":1,"stat_type":"counter"},{"name":"status_count_per_workspace","sample_rate":1,"stat_type":"counter"},{"name":"status_count_per_user_per_route","sample_rate":1,"stat_type":"counter"},{"name":"shdict_usage","sample_rate":1,"stat_type":"gauge"}]; Kong Gateway 3.14: [{"name":"request_count","sample_rate":1,"stat_type":"counter"},{"name":"latency","stat_type":"timer"},{"name":"request_size","sample_rate":1,"stat_type":"counter"},{"name":"status_count","sample_rate":1,"stat_type":"counter"},{"name":"response_size","sample_rate":1,"stat_type":"counter"},{"name":"unique_users","stat_type":"set"},{"name":"request_per_user","sample_rate":1,"stat_type":"counter"},{"name":"upstream_latency","stat_type":"timer"},{"name":"kong_latency","stat_type":"timer"},{"name":"status_count_per_user","sample_rate":1,"stat_type":"counter"},{"name":"status_count_per_workspace","sample_rate":1,"stat_type":"counter"},{"name":"status_count_per_user_per_route","sample_rate":1,"stat_type":"counter"},{"name":"shdict_usage","sample_rate":1,"stat_type":"gauge"},{"name":"cache_datastore_hits_total","sample_rate":1,"stat_type":"counter"},{"name":"cache_datastore_misses_total","sample_rate":1,"stat_type":"counter"}]
   */
  metrics?: Array<{
    /** Authenticated user detail. */
    consumer_identifier?: 'consumer_id' | 'custom_id' | 'username' | null;
    /**
     * StatsD metric’s name.
     * Kong Gateway 3.14 only values: `'cache_datastore_hits_total'`, `'cache_datastore_misses_total'`.
     */
    name:
      | 'kong_latency'
      | 'latency'
      | 'request_count'
      | 'request_per_user'
      | 'request_size'
      | 'response_size'
      | 'shdict_usage'
      | 'status_count'
      | 'status_count_per_user'
      | 'status_count_per_user_per_route'
      | 'status_count_per_workspace'
      | 'unique_users'
      | 'upstream_latency'
      | 'cache_datastore_hits_total'
      | 'cache_datastore_misses_total';
    /** Sampling rate */
    sample_rate?: number | null;
    /** Service detail. */
    service_identifier?:
      | 'service_host'
      | 'service_id'
      | 'service_name'
      | 'service_name_or_host'
      | null;
    /** Determines what sort of event a metric represents. */
    stat_type: 'counter' | 'gauge' | 'histogram' | 'meter' | 'set' | 'timer';
    /** Workspace detail. */
    workspace_identifier?: 'workspace_id' | 'workspace_name' | null;
  }> | null;
  /**
   * The port of StatsD server to send data to.
   * @default 8125
   */
  port?: number | null;
  /**
   * String to prefix to each metric's name.
   * @default 'kong'
   */
  prefix?: string | null;
  queue?: {
    /**
     * The number of of queue delivery timers. -1 indicates unlimited.
     * @default 1
     */
    concurrency_limit?: -1 | 1 | null;
    /**
     * Time in seconds before the initial retry is made for a failing batch.
     * @default 0.01
     */
    initial_retry_delay?: number | null;
    /**
     * Maximum number of entries that can be processed at a time.
     * @default 1
     */
    max_batch_size?: number | null;
    /** Maximum number of bytes that can be waiting on a queue, requires string content. */
    max_bytes?: number | null;
    /**
     * Maximum number of (fractional) seconds to elapse after the first entry was queued before the queue starts calling the handler.
     * @default 1
     */
    max_coalescing_delay?: number | null;
    /**
     * Maximum number of entries that can be waiting on the queue.
     * @default 10000
     */
    max_entries?: number | null;
    /**
     * Maximum time in seconds between retries, caps exponential backoff.
     * @default 60
     */
    max_retry_delay?: number | null;
    /**
     * Time in seconds before the queue gives up calling a failed handler for a batch.
     * @default 60
     */
    max_retry_time?: number | null;
  } | null;
  /** @deprecated statsd: config.queue_size is deprecated, please use config.queue.max_batch_size instead */
  queue_size?: number | null;
  /** @deprecated statsd: config.retry_count no longer works, please use config.queue.max_retry_time instead */
  retry_count?: number | null;
  /** @default 'service_name_or_host' */
  service_identifier_default?:
    | 'service_host'
    | 'service_id'
    | 'service_name'
    | 'service_name_or_host'
    | null;
  tag_style?: 'dogstatsd' | 'influxdb' | 'librato' | 'signalfx' | null;
  /** @default 0 */
  udp_packet_size?: number | null;
  /** @default false */
  use_tcp?: boolean | null;
  /** @default 'workspace_id' */
  workspace_identifier_default?: 'workspace_id' | 'workspace_name' | null;
}

