/** Configuration for the `zipkin` (Zipkin) plugin. */
export interface ZipkinConfig {
  /**
   * An integer representing a timeout in milliseconds. Must be between 0 and 2^31-2.
   * @default 2000
   */
  connect_timeout?: number | null;
  /**
   * Allows specifying the type of header to be added to requests with no pre-existing tracing headers and when `config.header_type` is set to `"preserve"`. When `header_type` is set to any other value, `default_header_type` is ignored.
   * Kong Gateway 3.14 only values: `'instana'`.
   * @default 'b3'
   * @deprecated zipkin: config.default_header_type is deprecated, please use config.propagation.default_format instead
   */
  default_header_type?:
    | 'aws'
    | 'b3'
    | 'b3-single'
    | 'datadog'
    | 'gcp'
    | 'jaeger'
    | 'ot'
    | 'w3c'
    | 'instana'
    | null;
  /** Set a default service name to override `unknown-service-name` in the Zipkin spans. */
  default_service_name?: string | null;
  /**
   * All HTTP requests going through the plugin are tagged with a tracing HTTP request. This property codifies what kind of tracing header the plugin expects on incoming requests
   * Kong Gateway 3.14 only values: `'instana'`.
   * @default 'preserve'
   * @deprecated zipkin: config.header_type is deprecated, please use config.propagation options instead
   */
  header_type?:
    | 'aws'
    | 'b3'
    | 'b3-single'
    | 'datadog'
    | 'gcp'
    | 'ignore'
    | 'jaeger'
    | 'ot'
    | 'preserve'
    | 'w3c'
    | 'instana'
    | null;
  /** A string representing a URL, such as https://example.com/path/to/resource?q=search. */
  http_endpoint?: string | null;
  http_response_header_for_traceid?: string | null;
  /**
   * Specify whether to include the HTTP path in the span name.
   * @default 'method'
   */
  http_span_name?: 'method' | 'method_path' | null;
  /**
   * Specify whether the credential of the currently authenticated consumer should be included in metadata sent to the Zipkin server.
   * @default true
   */
  include_credential?: boolean | null;
  /**
   * The name of the service as displayed in Zipkin.
   * @default 'kong'
   */
  local_service_name?: string | null;
  /**
   * Specify whether to include the duration of each phase as an annotation or a tag.
   * @default 'annotations'
   */
  phase_duration_flavor?: 'annotations' | 'tags' | null;
  /** @default {"default_format":"b3"} */
  propagation?: {
    /** Header names to clear after context extraction. This allows to extract the context from a certain header and then remove it from the request, useful when extraction and injection are performed on different header formats and the original header should not be sent to the upstream. If left empty, no headers are cleared. */
    clear?: Array<string> | null;
    /**
     * The default header format to use when extractors did not match any format in the incoming headers and `inject` is configured with the value: `preserve`. This can happen when no tracing header was found in the request, or the incoming tracing header formats were not included in `extract`.
     * Kong Gateway 3.14 only values: `'instana'`.
     */
    default_format:
      | 'aws'
      | 'b3'
      | 'b3-single'
      | 'datadog'
      | 'gcp'
      | 'jaeger'
      | 'ot'
      | 'w3c'
      | 'instana';
    /**
     * Header formats used to extract tracing context from incoming requests. If multiple values are specified, the first one found will be used for extraction. If left empty, Kong will not extract any tracing context information from incoming requests and generate a trace with no parent and a new trace ID.
     * Kong Gateway 3.14 only values: `'instana'`.
     */
    extract?: Array<'aws' | 'b3' | 'datadog' | 'gcp' | 'jaeger' | 'ot' | 'w3c' | 'instana'> | null;
    /**
     * Header formats used to inject tracing context. The value `preserve` will use the same header format as the incoming request. If multiple values are specified, all of them will be used during injection. If left empty, Kong will not inject any tracing context information in outgoing requests.
     * Kong Gateway 3.14 only values: `'instana'`.
     */
    inject?: Array<
      | 'aws'
      | 'b3'
      | 'b3-single'
      | 'datadog'
      | 'gcp'
      | 'jaeger'
      | 'ot'
      | 'preserve'
      | 'w3c'
      | 'instana'
    > | null;
  } | null;
  queue?: {
    /**
     * The number of of queue delivery timers. -1 indicates unlimited.
     * @default 1
     */
    concurrency_limit?: -1 | 1 | null;
    /**
     * Time in seconds before the initial retry is made for a failing batch.
     * @default 0.01
     */
    initial_retry_delay?: number | null;
    /**
     * Maximum number of entries that can be processed at a time.
     * @default 1
     */
    max_batch_size?: number | null;
    /** Maximum number of bytes that can be waiting on a queue, requires string content. */
    max_bytes?: number | null;
    /**
     * Maximum number of (fractional) seconds to elapse after the first entry was queued before the queue starts calling the handler.
     * @default 1
     */
    max_coalescing_delay?: number | null;
    /**
     * Maximum number of entries that can be waiting on the queue.
     * @default 10000
     */
    max_entries?: number | null;
    /**
     * Maximum time in seconds between retries, caps exponential backoff.
     * @default 60
     */
    max_retry_delay?: number | null;
    /**
     * Time in seconds before the queue gives up calling a failed handler for a batch.
     * @default 60
     */
    max_retry_time?: number | null;
  } | null;
  /**
   * An integer representing a timeout in milliseconds. Must be between 0 and 2^31-2.
   * @default 5000
   */
  read_timeout?: number | null;
  /**
   * How often to sample requests that do not contain trace IDs. Set to `0` to turn sampling off, or to `1` to sample **all** requests.
   * @default 0.001
   */
  sample_ratio?: number | null;
  /**
   * An integer representing a timeout in milliseconds. Must be between 0 and 2^31-2.
   * @default 5000
   */
  send_timeout?: number | null;
  /** The tags specified on this property will be added to the generated request traces. */
  static_tags?: Array<{
    name: string;
    value: string;
  }> | null;
  /**
   * The Zipkin plugin will add extra headers to the tags associated with any HTTP requests that come with a header named as configured by this property.
   * @default 'Zipkin-Tags'
   */
  tags_header?: string | null;
  /**
   * The length in bytes of each request's Trace ID.
   * @default 16
   */
  traceid_byte_count?: 8 | 16 | null;
}

/** Mapping from first-class Kong plugin name to its configuration type. */
export interface PluginConfigs {
  acl: AclConfig;
  acme: AcmeConfig;
  'ai-prompt-decorator': AiPromptDecoratorConfig;
  'ai-prompt-guard': AiPromptGuardConfig;
  'ai-prompt-template': AiPromptTemplateConfig;
  'ai-proxy': AiProxyConfig;
  'ai-request-transformer': AiRequestTransformerConfig;
  'ai-response-transformer': AiResponseTransformerConfig;
  'aws-lambda': AwsLambdaConfig;
  'azure-functions': AzureFunctionsConfig;
  'basic-auth': BasicAuthConfig;
  'bot-detection': BotDetectionConfig;
  'correlation-id': CorrelationIdConfig;
  cors: CorsConfig;
  datadog: DatadogConfig;
  'file-log': FileLogConfig;
  'grpc-gateway': GrpcGatewayConfig;
  'grpc-web': GrpcWebConfig;
  'hmac-auth': HmacAuthConfig;
  'http-log': HttpLogConfig;
  'ip-restriction': IpRestrictionConfig;
  jwt: JwtConfig;
  'key-auth': KeyAuthConfig;
  'ldap-auth': LdapAuthConfig;
  loggly: LogglyConfig;
  oauth2: Oauth2Config;
  opentelemetry: OpentelemetryConfig;
  'post-function': PostFunctionConfig;
  'pre-function': PreFunctionConfig;
  prometheus: PrometheusConfig;
  'proxy-cache': ProxyCacheConfig;
  'rate-limiting': RateLimitingConfig;
  redirect: RedirectConfig;
  'request-size-limiting': RequestSizeLimitingConfig;
  'request-termination': RequestTerminationConfig;
  'request-transformer': RequestTransformerConfig;
  'response-ratelimiting': ResponseRatelimitingConfig;
  'response-transformer': ResponseTransformerConfig;
  session: SessionConfig;
  'standard-webhooks': StandardWebhooksConfig;
  statsd: StatsdConfig;
  syslog: SyslogConfig;
  'tcp-log': TcpLogConfig;
  'udp-log': UdpLogConfig;
  zipkin: ZipkinConfig;
}

/** Union of all first-class Kong plugin names. */
export type PluginName = keyof PluginConfigs;

/** Configuration type for plugin `N`, falling back to `Record<string, unknown>` for custom plugins. */
export type ConfigOf<N extends string> = N extends PluginName
  ? PluginConfigs[N]
  : Record<string, unknown>;

/** Scope at which a Kong plugin can be attached. */
export type PluginScopeName = 'global' | 'service' | 'route' | 'consumer';

/** Metadata describing a first-class Kong plugin. */
export interface PluginInfo {
  /** Plugin category. */
  readonly category: string;
  /** Human-readable plugin title. */
  readonly title: string;
  /** Recorded Kong targets that include this plugin. */
  readonly targets: readonly string[];
  /** Scopes at which the plugin can be attached. */
  readonly scopes: readonly PluginScopeName[];
  /** Protocols supported by the plugin across recorded targets. */
  readonly protocols: readonly string[];
}

